/* Signature Morse Code Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Sig-SOS": "Prosign-style, from SOS: 'signal of salvation'.", "Sig-CQ": "Prosign-style, from CQ: 'seeking kin'.", "Sig-73": "Prosign-style, from 73: 'seventy-three blessings'.", "Sig-Omni": "From omni- (all): 'all-hearing'.", "Sig-Dahdit": "From dah-dit (the letter A).", "Sig-Beacon": "From beacon: 'the guiding signal'.", "S1GNA": "Signature callsign-style surname.", "M0RSE": "Signature callsign-style surname.", "D1TD AH": "Signature callsign-style surname.", "B3AC0N": "Signature callsign-style surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Sig-SOS';
console.log(lookup(q));

